(() => {
  'use strict';
  const P=ProwayPresentation,storageKey='proway-preview-wide-designs-20261022',client='ASIS · ejemplo',folio='PRW-PRUEBA-001';
  const areas=[['pedido','Pedido','▤','CAPTURA Y ORGANIZACIÓN','Selecciona prendas por grupo y aplícales un diseño ya cargado.'],['biblioteca','Biblioteca de diseños','▧','DISEÑOS ANTES DE CAPTURAR','Carga primero el frente y la espalda. Después reutiliza el modelo en los grupos que selecciones.'],['cotizacion','Cotización','＄','REVISIÓN DEL CLIENTE','Los nombres, tallas y diseños quedan ordenados también en la cotización.'],['diseno','Taller · Diseño','✎','QUÉ IMPRIMIR','Una lista ordenada para copiar nombres y preparar las impresiones.'],['sublimacion','Sublimación','◈','CONTROL DEL TALLER','Conteo por talla y corte. Las tarifas de esta prueba son solo de ejemplo.'],['costura','Costura','✂','ARMADO POR TALLA','La misma secuencia de prendas para preparar el trabajo de costura.'],['empaque','Empaque','□','REVISIÓN FINAL','Verifica el diseño, la persona, la talla y el corte de cada prenda.'],['etiquetas','Etiquetas','▱','IMPRESIÓN TAMAÑO CARTA','Todas las etiquetas visibles antes de exportar. Una etiqueta por pieza.'],['envio','Envío','➜','LISTADO DE ENTREGA','Destinatarios y prendas en el mismo orden que la preparación del pedido.']];
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money=x=>new Intl.NumberFormat('es-MX',{style:'currency',currency:'MXN'}).format(x),clone=x=>JSON.parse(JSON.stringify(x));
  const root=document.getElementById('area-content'),logo=document.getElementById('brand-logo').src;
  function sampleView(side,label){const back=side==='back';const svg='<svg xmlns="http://www.w3.org/2000/svg" width="500" height="650" viewBox="0 0 500 650"><rect width="500" height="650" fill="#f4f7f5"/><path d="M165 100 110 140 55 230 130 270 150 230 150 515 350 515 350 230 370 270 445 230 390 140 335 100 290 125 210 125Z" fill="#fff" stroke="#9fb3a5" stroke-width="4"/><path d="M210 125Q250 '+(back?'155':'195')+' 290 125" fill="none" stroke="#9fb3a5" stroke-width="4"/><text x="250" y="285" font-family="Arial" font-size="23" text-anchor="middle" fill="#52715c">'+esc(label)+'</text><text x="250" y="325" font-family="Arial" font-size="17" text-anchor="middle" fill="#718577">'+(back?'ESPALDA':'FRENTE')+'</text><text x="250" y="570" font-family="Arial" font-size="16" text-anchor="middle" fill="#87988c">VISTA DE MUESTRA · REEMPLAZAR</text></svg>';return 'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);}
  function seed(){const designs=['ASIS-SEC','ASIS-PREPA','ASIS-PERSONAL'].map((name,i)=>({id:'design-'+(i+1),name,front:sampleView('front',name),back:sampleView('back',name),sample:true}));
    const input=[['04','Butarga','G','Mujer',1,'Azul','design-2'],['01','Butarga','CH','Mujer',2,'Blanco','design-1'],['10','Playera','12','Hombre',1,'Azul','design-1'],['02','Butarga','M','Hombre',1,'Azul','design-2'],['03','Playera','8','Mujer',2,'Blanco','design-1'],['01','Short','M','Mujer',1,'Azul','design-1'],['05','Playera','XG','Hombre',1,'Blanco',null],['06','Butarga','CH','Hombre',1,'Blanco',null],['07','Short','G','Mujer',2,'Azul','design-2'],['08','Playera','16','Hombre',1,'Blanco',null],['09','Butarga','XXG','Hombre',1,'Azul','design-3'],['02','Short','M','Hombre',1,'Azul','design-2'],['11','Playera','6','Mujer',1,'Blanco',null],['12','Butarga','4XG','Hombre',1,'Blanco','design-3'],['10','Short','12','Hombre',2,'Azul','design-1'],['03','Short','8','Mujer',1,'Blanco','design-1'],['04','Playera','G','Mujer',1,'Azul','design-2'],['05','Butarga','XXXG','Hombre',1,'Blanco',null]];
    return {designs,rows:input.map((x,i)=>({id:'garment-'+(i+1),person:'Persona '+Number(x[0]),printed:'PERSONA '+Number(x[0])+' · #'+x[0],product:x[1],size:x[2],cut:x[3],qty:x[4],color:x[5],designId:x[6],price:x[1]==='Butarga'?800:x[1]==='Playera'?300:200,cost:x[1]==='Butarga'?120:x[1]==='Playera'?80:45})),selectedDesign:'design-1'};
  }
  let state=seed();try{const stored=JSON.parse(localStorage.getItem(storageKey)||'null');if(stored?.rows?.length&&stored?.designs?.length)state=stored;}catch{}
  let area='pedido',sort='size',selected=new Set(),filter={search:'',product:'*',size:'*',design:'*'},noticeTimer;
  const design=id=>state.designs.find(x=>x.id===id),designName=row=>design(row.designId)?.name||'Sin asignar';
  function save(){try{localStorage.setItem(storageKey,JSON.stringify(state));}catch{notify('La prueba sigue abierta; este navegador no permitió guardar la copia local.');}}
  function notify(message){const n=document.getElementById('notice');n.textContent=message;n.hidden=false;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>{n.hidden=true;},7000);}
  const count=rows=>rows.reduce((n,x)=>n+x.qty,0);
  function visible(){const q=filter.search.trim().toLocaleLowerCase('es-MX');return P.numbered(state.rows.filter(x=>(filter.product==='*'||x.product===filter.product)&&(filter.size==='*'||x.size===filter.size)&&(filter.design==='*'||(filter.design==='none'?!x.designId:x.designId===filter.design))&&[x.person,x.printed,x.color,x.size,designName(x)].join(' ').toLocaleLowerCase('es-MX').includes(q)),sort);}
  function allRows(){return P.numbered(state.rows,sort);}
  function renderStats(){document.getElementById('statistics').innerHTML=[['Prendas del pedido',count(state.rows),'piezas'],['Personas',new Set(state.rows.map(x=>x.person)).size,'destinatarios'],['Diseños cargados',state.designs.length,'frente y espalda'],['Orden del listado',sort==='size'?'Talla':'Persona','menor a mayor']].map(([label,value,caption],i)=>'<div class="stat '+(i===0?'accent':'')+'"><small>'+label+'</small><strong>'+value+'</strong><span>'+caption+'</span></div>').join('');}
  function options(list,value){return list.map(([v,label])=>'<option value="'+esc(v)+'" '+(v===value?'selected':'')+'>'+esc(label)+'</option>').join('');}
  function orderControl(){return '<div class="export-order"><label class="field">Orden en pantalla, vista previa y exportación<select id="sort-order">'+options([['size','Talla de menor a mayor → persona'],['person','Persona → talla de menor a mayor']],sort)+'</select></label><small>La columna N.º se numera después de ordenar.<br>El número impreso de la prenda se conserva aparte.</small></div>';}
  function libraryMarkup(large=false){return '<section class="panel '+(large?'gallery-area':'')+'"><div class="split-heading"><h2><span class="step-number">1</span>Precargar diseños</h2><span class="pill">'+state.designs.length+' modelos</span></div><p class="help">Pon un nombre al modelo y carga su frente y espalda desde tu galería. Las imágenes de muestra solo sirven para probar; reemplázalas por las tuyas. Toca una imagen para ampliarla.</p><div class="library-grid">'+state.designs.map(d=>'<article class="design-card '+(state.selectedDesign===d.id?'selected':'')+'" data-design-card="'+esc(d.id)+'"><div class="design-title"><strong>'+esc(d.name)+'</strong><span class="pill '+(d.sample?'pending':'')+'">'+(d.sample?'Muestra':'Cargado')+'</span></div><div class="design-views">'+['front','back'].map(side=>'<div class="design-view"><button type="button" data-enlarge="'+esc(d.id)+'" data-side="'+side+'" aria-label="Ampliar '+esc(d.name)+' '+side+'"><img alt="'+esc(d.name)+' · '+(side==='front'?'Frente':'Espalda')+'" src="'+esc(d[side]||sampleView(side,d.name))+'"></button><small>'+(side==='front'?'Frente':'Espalda')+'</small><label class="file-button">'+(d[side]?'Reemplazar':'Cargar imagen')+'<input type="file" accept="image/png,image/jpeg,image/webp" data-upload-design="'+esc(d.id)+'" data-side="'+side+'"></label></div>').join('')+'</div><button class="'+(state.selectedDesign===d.id?'primary':'secondary')+'" data-select-design="'+esc(d.id)+'">'+(state.selectedDesign===d.id?'✓ Diseño seleccionado':'Elegir este diseño')+'</button><div class="design-count">'+count(state.rows.filter(x=>x.designId===d.id))+' prendas con este modelo</div></article>').join('')+'</div><form id="new-design-form" class="new-design-form"><label class="field">Agregar otro modelo al mismo pedido<input id="new-design-name" maxlength="100" required placeholder="Ej. ASIS-ENTRENADORES"></label><button class="secondary" type="submit">＋ Crear espacio para diseño</button></form></section>';}
  function roster(rows,{checkboxes=false,price=false,cost=false}={}){return '<div class="table-wrap"><table class="roster"><thead><tr>'+(checkboxes?'<th>Elegir</th>':'')+'<th>N.º</th><th>Persona</th><th>Prenda</th><th>Talla</th><th>Corte</th><th>Cant.</th><th>Color</th><th>Diseño</th><th>Nombre y número impresos</th>'+(price?'<th>Precio base</th><th>Importe</th>':'')+(cost?'<th>Costo de muestra</th><th>Importe</th>':'')+'</tr></thead><tbody>'+rows.map(x=>'<tr data-garment="'+esc(x.id)+'" class="'+(selected.has(x.id)?'selected-row':'')+'">'+(checkboxes?'<td><input type="checkbox" data-select-row="'+esc(x.id)+'" '+(selected.has(x.id)?'checked':'')+' aria-label="Seleccionar '+esc(x.person+' '+x.product+' talla '+x.size)+'"></td>':'')+'<td class="line-number">'+x.lineNo+'</td><td class="person-name">'+esc(x.person)+'</td><td>'+esc(x.product)+'</td><td><span class="size-pill">'+esc(x.size)+'</span></td><td>'+esc(x.cut)+'</td><td>'+x.qty+'</td><td><span class="color-dot" style="background:'+(x.color==='Azul'?'#31578e':'#fff')+'"></span>'+esc(x.color)+'</td><td><span class="design-code '+(!x.designId?'empty':'')+'">'+esc(designName(x))+'</span></td><td>'+esc(x.printed)+'</td>'+(price?'<td>'+money(x.price)+'</td><td>'+money(x.price*x.qty)+'</td>':'')+(cost?'<td>'+money(x.cost)+'</td><td>'+money(x.cost*x.qty)+'</td>':'')+'</tr>').join('')+(!rows.length?'<tr><td colspan="14" class="empty">No hay prendas con estos filtros.</td></tr>':'')+'</tbody></table></div>';}
  function filters(){return '<div class="filter-bar"><label class="field">Buscar persona, número o color<input id="filter-search" value="'+esc(filter.search)+'" placeholder="Ej. Persona 2"></label><label class="field">Producto<select id="filter-product">'+options([['*','Todos'],...['Butarga','Playera','Short'].map(x=>[x,x])],filter.product)+'</select></label><label class="field">Talla<select id="filter-size">'+options([['*','Todas'],...[...new Set(state.rows.map(x=>x.size))].sort(P.compareSizes).map(x=>[x,x])],filter.size)+'</select></label><label class="field">Diseño actual<select id="filter-design">'+options([['*','Todos'],['none','Sin asignar'],...state.designs.map(x=>[x.id,x.name])],filter.design)+'</select></label></div>';}
  function assignmentMarkup(){const chosen=state.rows.filter(x=>selected.has(x.id)),d=design(state.selectedDesign);return '<div class="assignment-bar"><div><strong id="selected-total">'+count(chosen)+' prendas seleccionadas · '+chosen.length+' renglones</strong><small>Diseño preparado: <b>'+esc(d?.name||'Elige un modelo arriba')+'</b></small><small>Se aplicará a todas las piezas de los renglones marcados.</small></div><button class="primary" id="apply-design" '+(!chosen.length||!d||!(d.front||d.back)?'disabled':'')+'>Aplicar diseño a seleccionadas</button></div>';}
  function capture(){return libraryMarkup()+'<section class="panel"><div class="split-heading"><h2><span class="step-number">2</span>Seleccionar grupo de prendas</h2><span class="pill">Mismo pedido</span></div><p class="help">Filtra por talla, producto o diseño actual. Marca varias prendas y aplica el modelo de la biblioteca. Puedes repetir con los demás grupos.</p>'+orderControl()+filters()+'<div class="table-tools"><div class="tools-left"><button id="select-visible">Seleccionar las visibles</button><button id="clear-selection">Limpiar selección</button></div><span class="order-hint">'+visible().length+' renglones visibles · '+count(visible())+' prendas</span></div>'+roster(visible(),{checkboxes:true})+assignmentMarkup()+'</section>';}
  function labelMarkup(){const rows=P.pieces(state.rows,sort);return '<div class="labels-grid">'+rows.map(x=>'<article class="garment-label" data-label-no="'+x.lineNo+'"><div class="label-number"><span>N.º '+x.lineNo+' de '+rows.length+'</span><span>PROWAY</span></div><strong>'+esc(x.person)+'</strong>'+esc(x.product+' · Talla '+x.size+' · '+x.cut)+'<br>'+esc(x.printed)+'<br>Color: '+esc(x.color)+'<br>Diseño: '+esc(designName(x))+'<br><small>'+folio+'</small></article>').join('')+'</div>';}
  function documentData(which=area){const rows=which==='etiquetas'?P.pieces(state.rows,sort):allRows();const heads=['N.º','Persona','Prenda','Talla','Corte','Cantidad','Color','Diseño','Nombre / número a imprimir'];const body=rows.map(x=>[x.lineNo,x.person,x.product,x.size,x.cut,x.qty,x.color,designName(x),x.printed]);if(which==='cotizacion'||which==='sublimacion'){heads.push(which==='cotizacion'?'Precio base':'Costo de muestra','Importe');body.forEach((line,i)=>line.push(rows[i][which==='cotizacion'?'price':'cost'],rows[i][which==='cotizacion'?'price':'cost']*rows[i].qty));}return {heads,body,rows,title:areas.find(x=>x[0]===which)?.[1]||'Pedido',mode:sort,total:rows.reduce((n,x)=>n+x.qty*(which==='sublimacion'?x.cost:x.price),0)};}
  function designsDocument(){const ids=new Set(state.rows.map(x=>x.designId).filter(Boolean));return '<div class="doc-designs">'+state.designs.filter(x=>ids.has(x.id)).map(d=>'<section><strong>'+esc(d.name)+'</strong>'+['front','back'].map(side=>d[side]?'<img alt="'+esc(d.name)+' · '+(side==='front'?'Frente':'Espalda')+'" src="'+esc(d[side])+'">':'').join('')+'</section>').join('')+'</div>';}
  function documentMarkup(which=area){const d=documentData(which);return '<div class="preview-sheet"><div class="doc-header"><img src="'+esc(logo)+'" alt="Proway"><div><h2>'+esc(d.title)+'</h2><small>'+folio+'</small><small>PRUEBA · DATOS DE EJEMPLO</small></div></div><div class="doc-meta"><div><strong>'+client+'</strong>proway.com.mx · WhatsApp 33 1007 9695</div><div><strong>'+count(state.rows)+' prendas · '+new Set(state.rows.map(x=>x.person)).size+' personas</strong>Orden: '+(sort==='size'?'talla → persona':'persona → talla')+'</div></div>'+(which==='etiquetas'?labelMarkup():roster(d.rows,{price:which==='cotizacion',cost:which==='sublimacion'}))+(['cotizacion','sublimacion'].includes(which)?'<div class="doc-total"><strong>Total de ejemplo · precio base</strong><strong>'+money(d.total)+'</strong></div>':'')+(['cotizacion','diseno','costura','biblioteca'].includes(which)?designsDocument():'')+'<p class="doc-note">Tamaño carta. La vista previa y las descargas usan la misma lista ordenada. Los datos, importes y dibujos de esta prueba son ilustrativos.</p></div>';}
  function department(){const extra=area==='empaque'?'<div class="screen-checklist"><label><input type="checkbox">Tallas y corte revisados</label><label><input type="checkbox">Nombre y número revisados</label><label><input type="checkbox">Diseño y color coinciden</label><label><input type="checkbox">Piezas y etiquetas completas</label></div>':'';return '<section class="panel"><div class="department-intro"><div><h2>'+esc(areas.find(x=>x[0]===area)[1])+' · listado final</h2><p class="help">El orden se conserva al revisar, descargar e imprimir.</p></div><span class="pill">'+count(state.rows)+' prendas</span></div>'+orderControl()+extra+(area==='sublimacion'?'<div class="proposal-note">Tarifas de muestra para probar la presentación. Las tablas reales de sublimación de tu aplicación se conservarán.</div>':'')+documentMarkup()+'</section>';}
  function render(){const active=document.activeElement,id=active?.id,range=active?.tagName==='INPUT'&&active.type==='text'?[active.selectionStart,active.selectionEnd]:null;const a=areas.find(x=>x[0]===area);document.getElementById('area-title').textContent=a[1];document.getElementById('area-eyebrow').textContent=a[3];document.getElementById('area-subtitle').textContent=a[4];document.getElementById('navigation').innerHTML=areas.map(x=>'<button data-area="'+x[0]+'" '+(x[0]===area?'aria-current="page"':'')+'><span class="nav-icon" aria-hidden="true">'+x[2]+'</span><span>'+esc(x[1])+'</span></button>').join('');renderStats();root.innerHTML=area==='pedido'?capture():area==='biblioteca'?libraryMarkup(true)+'<section class="panel"><h2><span class="step-number">2</span>Asignar a grupos</h2><p class="help">Cuando los modelos estén cargados, elige las prendas del pedido. No necesitas crear otro folio.</p><button class="primary" data-area="pedido">Ir a seleccionar prendas →</button></section>':department();if(id){const next=document.getElementById(id);if(next){next.focus({preventScroll:true});if(range)next.setSelectionRange(...range);}}}
  function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),1000);}
  function filename(ext){return 'Proway-ASIS-'+area+'-PRUEBA.'+ext;}
  async function png(src){if(!src)return null;const img=new Image();img.src=src;await img.decode();const scale=Math.min(1,1200/Math.max(img.naturalWidth,img.naturalHeight)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(img,0,0,canvas.width,canvas.height);return {data:canvas.toDataURL('image/png'),width:canvas.width,height:canvas.height};}
  async function pdfExport(){const d=documentData(),label=area==='etiquetas',doc=new jspdf.jsPDF({orientation:label||area==='cotizacion'?'portrait':'landscape',unit:'mm',format:'letter'});const width=doc.internal.pageSize.getWidth(),height=doc.internal.pageSize.getHeight(),margin=12;const brand=await png(logo);if(!label){doc.addImage(brand.data,'PNG',margin,9,48,17);doc.setFontSize(17);doc.setTextColor(23,100,67);doc.text(d.title,width-margin,18,{align:'right'});doc.setFontSize(9);doc.setTextColor(80);doc.text(client+' | '+folio,margin,35);doc.text('PRUEBA - '+(sort==='size'?'Tallas de menor a mayor / persona':'Persona / tallas de menor a mayor'),margin,41);doc.autoTable({startY:47,margin:{left:margin,right:margin,bottom:16},head:[d.heads],body:d.body.map(line=>line.map((v,i)=>typeof v==='number'&&i>8?money(v):v)),styles:{font:'helvetica',fontSize:area==='cotizacion'?7:8,cellPadding:2.7,overflow:'linebreak'},headStyles:{fillColor:[23,100,67]},alternateRowStyles:{fillColor:[244,248,245]},didDrawPage:()=>{doc.setFontSize(8);doc.setTextColor(100);doc.text('proway.com.mx | WhatsApp 33 1007 9695 | Datos de ejemplo',margin,height-8);}});let y=doc.lastAutoTable.finalY+10;if(['cotizacion','sublimacion'].includes(area)){if(y>height-24){doc.addPage();y=20;}doc.setFontSize(11);doc.setTextColor(23,100,67);doc.text('Total de ejemplo: '+money(d.total),width-margin,y,{align:'right'});}
      if(['cotizacion','diseno','costura','biblioteca','pedido'].includes(area)){for(const model of state.designs.filter(x=>state.rows.some(r=>r.designId===x.id))){const art=await Promise.all(['front','back'].map(side=>png(model[side])));doc.addPage();doc.setFontSize(15);doc.text(model.name,margin,18);const boxWidth=(width-3*margin)/2,boxHeight=height-55;for(let i=0;i<2;i++){const x=margin+i*(boxWidth+margin);doc.setFontSize(10);doc.text(i?'Espalda':'Frente',x+boxWidth/2,28,{align:'center'});if(art[i]){const scale=Math.min(boxWidth/art[i].width,boxHeight/art[i].height),w=art[i].width*scale,h=art[i].height*scale;doc.addImage(art[i].data,'PNG',x+(boxWidth-w)/2,35,w,h);}}}}
    }else{const columns=3,lines=8,boxW=(width-2*margin)/columns,boxH=(height-2*margin)/lines;d.rows.forEach((r,i)=>{if(i&&i%24===0)doc.addPage();const position=i%24,x=margin+(position%columns)*boxW,y=margin+Math.floor(position/columns)*boxH;doc.setDrawColor(165,190,173);doc.setLineDashPattern([1,1],0);doc.rect(x,y,boxW,boxH);doc.setLineDashPattern([],0);doc.setFontSize(8);doc.setTextColor(23,100,67);doc.text('N.º '+r.lineNo+' / '+d.rows.length+'   PROWAY',x+3,y+5);doc.setTextColor(30);doc.setFontSize(9);doc.text(r.person,x+3,y+10);doc.setFontSize(7);const text=[r.product+' | Talla '+r.size+' | '+r.cut,r.printed,r.color+' | '+designName(r),folio];doc.text(doc.splitTextToSize(text.join('\n'),boxW-6),x+3,y+14);});}download(doc.output('blob'),filename('pdf'));notify('PDF descargado en tamaño carta, con el mismo orden de la vista previa.');return doc;}
  async function excelExport(){const d=documentData(),wb=new ExcelJS.Workbook();wb.creator='Proway · prueba';const sheet=wb.addWorksheet('Listado ordenado');sheet.pageSetup={paperSize:1,orientation:'landscape',fitToPage:true,fitToWidth:1,fitToHeight:0};sheet.addRow(['PROWAY · '+d.title]);sheet.addRow([client,folio]);sheet.addRow(['PRUEBA · Datos de ejemplo · Orden: '+(sort==='size'?'talla → persona':'persona → talla')]);sheet.addRow([]);sheet.addRow(d.heads);d.body.forEach(line=>sheet.addRow(line));sheet.columns=d.heads.map((h,i)=>({width:i===1||i===8?28:i===7?25:14}));sheet.eachRow((row,n)=>{row.height=n===1?28:24;row.eachCell(c=>{c.font={name:'Arial',size:11};c.alignment={vertical:'middle',wrapText:true};if(n===5){c.font={name:'Arial',size:11,bold:true,color:{argb:'FFFFFFFF'}};c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF176443'}};}if(n>5&&n%2===0)c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFF1F7F2'}};});});sheet.views=[{state:'frozen',ySplit:5}];sheet.autoFilter={from:'A5',to:{row:5,column:d.heads.length}};if(['cotizacion','sublimacion'].includes(area))sheet.addRow(['Total de ejemplo',d.total]);
    const artSheet=wb.addWorksheet('Diseños');artSheet.columns=[{width:7},{width:34},{width:7},{width:34}];let anchor=0;for(const model of state.designs.filter(x=>state.rows.some(r=>r.designId===x.id))){const row=artSheet.getRow(anchor+1);row.getCell(1).value=model.name;row.getCell(1).font={name:'Arial',size:14,bold:true};for(const [i,side] of ['front','back'].entries()){const image=await png(model[side]);if(image){const id=wb.addImage({base64:image.data,extension:'png'}),scale=Math.min(250/image.width,320/image.height);artSheet.addImage(id,{tl:{col:i*2,row:anchor+2},ext:{width:image.width*scale,height:image.height*scale}});}}anchor+=20;}download(new Blob([await wb.xlsx.writeBuffer()],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),filename('xlsx'));notify('Excel descargado: tallas ordenadas, numeración e imágenes editables.');return wb;}
  function openDocument(){document.getElementById('document-title').textContent=areas.find(x=>x[0]===area)[1]+' · '+client;document.getElementById('document-preview').innerHTML=documentMarkup();document.getElementById('document-dialog').showModal();}
  async function exportAction(kind,button){if(button.disabled)return;button.disabled=true;try{await(kind==='pdf'?pdfExport():excelExport());}catch(e){notify('No se pudo preparar la descarga: '+e.message);}finally{button.disabled=false;}}
  document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.area){area=b.dataset.area;render();window.scrollTo({top:0,behavior:'smooth'});return;}if(b.dataset.selectDesign){state.selectedDesign=b.dataset.selectDesign;save();render();notify('Modelo elegido. Ahora marca las prendas a las que lo aplicarás.');return;}if(b.dataset.enlarge){const d=design(b.dataset.enlarge);document.getElementById('large-image').src=d[b.dataset.side]||sampleView(b.dataset.side,d.name);document.getElementById('image-dialog').showModal();return;}
    if(b.id==='select-visible'){visible().forEach(x=>selected.add(x.id));render();}if(b.id==='clear-selection'){selected.clear();render();}if(b.id==='apply-design'){const d=design(state.selectedDesign);if(!d||!selected.size)return;const qty=count(state.rows.filter(x=>selected.has(x.id)));state.rows.forEach(x=>{if(selected.has(x.id))x.designId=d.id;});selected.clear();save();render();notify(d.name+' aplicado a '+qty+' prendas del mismo pedido.');}
    if(b.id==='preview-document')openDocument();if(b.id==='close-document')document.getElementById('document-dialog').close();if(b.id==='close-image')document.getElementById('image-dialog').close();if(['download-pdf','modal-pdf'].includes(b.id))exportAction('pdf',b);if(['download-excel','modal-excel'].includes(b.id))exportAction('excel',b);
    if(b.id==='reset-demo'){const backdrop=document.createElement('div');backdrop.className='confirm-reset';backdrop.innerHTML='<div><h2>Reiniciar esta prueba</h2><p>Se quitarán solo los cambios e imágenes de este ejemplo. Tus pedidos reales de Proway se conservan.</p><button id="confirm-reset" class="primary">Reiniciar ejemplo</button><button id="cancel-reset">Conservar cambios</button></div>';document.body.append(backdrop);}if(b.id==='cancel-reset')b.closest('.confirm-reset').remove();if(b.id==='confirm-reset'){state=seed();selected.clear();filter={search:'',product:'*',size:'*',design:'*'};save();render();b.closest('.confirm-reset').remove();notify('Datos de ejemplo recuperados.');}
  });
  document.addEventListener('change',async e=>{const x=e.target;if(x.dataset.selectRow){x.checked?selected.add(x.dataset.selectRow):selected.delete(x.dataset.selectRow);render();}if(x.id==='sort-order'){sort=x.value;render();}if(x.id==='filter-product'||x.id==='filter-size'||x.id==='filter-design'){filter[x.id.slice(7)]=x.value;render();}if(x.dataset.uploadDesign){const file=x.files?.[0],d=design(x.dataset.uploadDesign);if(!file||!d)return;if(!/^image\/(png|jpeg|webp)$/.test(file.type)||file.size>12*1024*1024){notify('Elige una imagen JPG, PNG o WebP de hasta 12 MB.');return;}try{const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);});const optimized=await png(data);d[x.dataset.side]=optimized.data;d.sample=false;save();render();notify('Imagen guardada en '+d.name+'. Puedes usar este modelo en varios grupos.');}catch{notify('No se pudo abrir la imagen. Prueba con JPG o PNG.');}}});
  document.addEventListener('input',e=>{if(e.target.id==='filter-search'){filter.search=e.target.value;render();}});
  document.addEventListener('submit',e=>{if(e.target.id!=='new-design-form')return;e.preventDefault();const name=document.getElementById('new-design-name').value.trim();if(!name)return;if(state.designs.some(x=>x.name.toLocaleLowerCase('es-MX')===name.toLocaleLowerCase('es-MX'))){notify('Ya existe un modelo con ese nombre. Elígelo en la biblioteca.');return;}if(state.designs.length>=9){notify('La prueba admite hasta 9 modelos por pedido, igual que la versión actual.');return;}const d={id:'design-'+Date.now(),name,front:null,back:null,sample:false};state.designs.push(d);state.selectedDesign=d.id;save();render();notify('Modelo creado. Carga su frente o espalda antes de asignarlo.');document.querySelector('[data-design-card="'+d.id+'"]')?.scrollIntoView({block:'center',behavior:'smooth'});});
  window.ProwayWidePreview={getState:()=>clone(state),documentData,allRows,visible,setArea:value=>{if(areas.some(x=>x[0]===value)){area=value;render();}},getArea:()=>area,exportPdf:pdfExport,exportExcel:excelExport};
  render();
})();
